function ChoiceChips({ options }) {
  const [on, setOn] = useState(() => new Set());

  const toggle = (opt) =>
    setOn((prev) => {
      const next = new Set(prev);
      next.has(opt) ? next.delete(opt) : next.add(opt);
      return next;
    });

  return (
    <div>
      {options.map((opt) => (
        <button
          key={opt}
          className={on.has(opt) ? 'chip on' : 'chip'}
          onClick={() => toggle(opt)}
        >
          {opt}
        </button>
      ))}
    </div>
  );
}

