function ShakeInput() {
  const [error, setError] = useState(false);

  const submit = () => {
    setError(false);
    requestAnimationFrame(() => setError(true));
    setTimeout(() => setError(false), 500);
  };

  return (
    <input
      onBlur={submit}
      className={error ? 'error' : ''}
      style={{ animation: error ? 'shake-x .45s cubic-bezier(.36,.07,.19,.97) both' : 'none' }}
    />
  );
}

